template <typename T>
class std::vector {
public:
    // Iterator-based construction template
    template <typename InputIterator>
    vector(InputIterator first, InputIterator last);
};

// Usage Example
std::vector<int> source = {10, 20, 30};
// Iterator deduction (InputIterator = std::vector<int>::iterator)
std::vector<int> target(source.begin(), source.end());

// Iterators determine range and type
std::list<float> data = {1.1f, 2.2f};
// Target constructed from list, elements converted to double
std::vector<double> results(data.begin(), data.end());
